#include "buyer_demand.hpp"
#include <cassert>
#include <iostream>
int main(){using namespace perekup;Json s={{"gameMs",200*day},{"bank",{{"loans",Json::array()}}},{"career",{{"reputation",50},{"cycle",0},{"assistant",false}}}};Json car={{"price",200000},{"name","Toyota RAV4"}};assert(nativeCollectorBuyerFactor(s)==1);assert(nativeCareerBuyerFactor(s,car)==1);s["career"]["cycle"]=1;assert(nativeCareerBuyerFactor(s,car)==.8);s["career"]["reputation"]=80;s["career"]["assistant"]=true;assert(std::abs(nativeCareerBuyerFactor(s,car)-.85*.75*.8)<1e-12);s["career"]["cycle"]=3;assert(std::abs(nativeCareerBuyerFactor(s,car)-.85*.75*.8)<1e-12);s["bank"]["loans"].push_back({{"status","active"},{"kind","micro"},{"arrearsCents",10000},{"principalCents",10000},{"interestCents",0},{"feesCents",0},{"nextDueAt",nullptr},{"overdueAt",0}});assert(nativeCollectorBuyerFactor(s)==3);s["gameMs"]=120*day;assert(nativeCollectorBuyerFactor(s)==2);s["gameMs"]=30*day;assert(nativeCollectorBuyerFactor(s)==1.5);s["gameMs"]=29*day;assert(nativeCollectorBuyerFactor(s)==1);std::cout<<"PASS buyer demand: reputation, assistant, SUV/budget events and debt thresholds\n";}
